package binding

type headerBinding struct{}

(headerBinding) Name() string => "header"

(headerBinding) Bind(req *http.Request, obj interface{})! {
mapHeader(obj, req.Header)?
return validate(obj)
}

mapHeader(ptr interface{}, h http.Header)! => mappingByPtr(ptr, headerSource(h), "header")

type headerSource map[string][]string

var _ setter=headerSource(nil)

(h headerSource) TrySet(value reflect.Value, field reflect.StructField, key string, opt setOptions)(bool,error) {
return setByForm(value, field, h, http.CanonicalHeaderKey(key), opt)
}
